<?php
require_once __DIR__.'/../includes/auth.php';requireRole('admin');$errors=[];if(isPost()){verifyCsrf();$values=['site_name'=>trim($_POST['site_name']??''),'site_description'=>trim($_POST['site_description']??''),'contact_email'=>mb_strtolower(trim($_POST['contact_email']??'')),'allow_registration'=>!empty($_POST['allow_registration'])?'1':'0'];if(mb_strlen($values['site_name'])<2||mb_strlen($values['site_name'])>100)$errors[]='يجب أن يكون اسم الموقع بين حرفين و100 حرف.';if(mb_strlen($values['site_description'])>1000)$errors[]='وصف الموقع يتجاوز 1000 حرف.';if(mb_strlen($values['contact_email'])>191||($values['contact_email']!==''&&!filter_var($values['contact_email'],FILTER_VALIDATE_EMAIL)))$errors[]='بريد التواصل غير صالح.';if(!$errors){$sql='INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)';$s=db()->prepare($sql);foreach($values as $k=>$v)$s->execute([$k,$v]);flash('success','تم حفظ الإعدادات.');redirect(url('admin/settings.php'));}}$pageTitle='إعدادات الموقع';require __DIR__.'/includes/header.php';?><div class="card stat-card mx-auto" style="max-width:800px"><div class="card-body p-4"><?php foreach($errors as $x):?><div class="alert alert-danger"><?=e($x)?></div><?php endforeach;?><form method="post"><?=csrfField()?><label class="form-label">اسم الموقع</label><input class="form-control mb-3" name="site_name" required value="<?=e($_POST['site_name']??setting('site_name','بوابة الأخبار'))?>"><label class="form-label">وصف الموقع</label><textarea class="form-control mb-3" name="site_description" rows="3"><?=e($_POST['site_description']??setting('site_description',''))?></textarea><label class="form-label">بريد التواصل</label><input class="form-control mb-3" type="email" name="contact_email" value="<?=e($_POST['contact_email']??setting('contact_email',''))?>"><div class="form-check form-switch mb-4"><input class="form-check-input" type="checkbox" name="allow_registration" value="1" <?=isset($_POST['csrf_token'])?(!empty($_POST['allow_registration'])?'checked':''):(setting('allow_registration','0')==='1'?'checked':'')?>><label class="form-check-label">السماح بالتسجيل العام</label></div><button class="btn btn-primary">حفظ الإعدادات</button></form></div></div><?php require __DIR__.'/includes/footer.php';?>
